## Performance Testing with Locust

```python
from locust import HttpUser, task, between
import json

class APIUser(HttpUser):
    """Simulated API user for load testing."""

    wait_time = between(1, 3)  # Wait 1-3 seconds between tasks

    def on_start(self):
        """Login and store token on user start."""
        response = self.client.post('/auth/login', json={
            'email': f'loadtest_{self.environment.runner.user_count}@test.com',
            'password': 'LoadTest123!'
        })
        self.token = response.json()['access_token']
        self.headers = {'Authorization': f'Bearer {self.token}'}

    @task(5)  # Weight: 5x more likely than others
    def list_items(self):
        """List items - most common operation."""
        with self.client.get(
            '/api/v1/items/',
            headers=self.headers,
            catch_response=True
        ) as response:
            if response.status_code == 200:
                response.success()
            else:
                response.failure(f'Status: {response.status_code}')

    @task(3)
    def get_single_item(self):
        """Get single item by ID."""
        item_id = 'known-test-item-id'
        self.client.get(
            f'/api/v1/items/{item_id}',
            headers=self.headers
        )

    @task(1)
    def create_item(self):
        """Create new item - less frequent."""
        self.client.post(
            '/api/v1/items/',
            headers=self.headers,
            json={
                'name': f'Load Test Item {self.environment.runner.user_count}',
                'price': 9.99
            }
        )

# Performance Thresholds
PERFORMANCE_TARGETS = {
    'list_items': {'p95': 200, 'p99': 500},      # milliseconds
    'get_single_item': {'p95': 100, 'p99': 200},
    'create_item': {'p95': 300, 'p99': 600},
}
```

### Load Test Profiles

| Profile | Users | Ramp-up | Duration | Use Case |
|---------|-------|---------|----------|----------|
| Smoke | 5 | 30s | 2min | Sanity check |
| Load | 100 | 5min | 30min | Normal load |
| Stress | 500 | 10min | 1hr | Peak capacity |
| Soak | 200 | 5min | 8hr | Memory leaks |
